import"./chunks/assets.DeKsZZ4W.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"Sub-Store 安全小贴士","description":"","frontmatter":{"title":"Sub-Store 安全小贴士"},"headers":[],"relativePath":"blog/posts/3481.md","filePath":"blog/posts/3481.md","lastUpdated":1784880411000}`),a={name:`blog/posts/3481.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="sub-store-安全小贴士" tabindex="-1">Sub-Store 安全小贴士 <a class="header-anchor" href="#sub-store-安全小贴士" aria-label="Permalink to “Sub-Store 安全小贴士”">​</a></h1><div class="telegram-content"><u><img class="telegram-custom-emoji" src="/telegram/AgADjgIAAvkj2EQ.webp" alt="🔗" loading="lazy" decoding="async"></u><u> Sub-Store 安全小贴士</u><br><br>1. 参考 <a href="https://hub.docker.com/r/xream/sub-store">文档</a> 不要开放 <code>SUB_STORE_BACKEND_API_HOST</code>, <code>SUB_STORE_BACKEND_API_PORT</code> 如果本机也不怎么安全, <code>SUB_STORE_BACKEND_MERGE=true</code> 可以保证本机访问也需要带 <code>SUB_STORE_FRONTEND_BACKEND_PATH</code><br><br>2. 请配置域名反代 HTTPS. 不要开放 IP 监听. 这样至少无聊的人不会用 IP+端口扫你<br><br>3. 不要泄露你的域名和 <code>SUB_STORE_FRONTEND_BACKEND_PATH</code>. 可使用分享功能 创建分享链接使用. 如果是分享给他人用, 可使用 <a href="/blog/posts/1428">上传订阅至其他 Gist</a> 或 <a href="/blog/posts/6208">上传订阅/文件到 WebDav</a> 由于现在支持 age 加密, 你用国内的 WebDav 服务都很安全了<br><br>4. 新版已经统一了响应. 可以在反代层面做这样的措施: <br><br>记录并封禁 <code>https://a.com*/(api|download|share)/*</code> 且 第一个 <code>*</code> 不是 <code>SUB_STORE_FRONTEND_BACKEND_PATH</code>(它是以 <code>/</code> 开头的) 的访问者<br><br>正常情况下 你自己肯定存了路径. 错误路径的尝试大概是别人知道了你的域名, 在爆你<br><br>或者参考群友的 <a href="https://t.me/zhetengsha_group/1011416">封禁频繁的 404 访问者</a> 自己访问没 404 的<br><br>5. 环境变量 <code>SUB_STORE_X_POWERED_BY</code> 可设置 自定义响应头中的 <code>X-Powered-By</code> 防止某些无聊的人来扫<br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/214/">Sub-Store 合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a> <img class="telegram-custom-emoji" src="/telegram/AgADbg0AAgj82Vc.webp" alt="🥰" loading="lazy" decoding="async"><a href="https://t.me/xream_bot">联系推广</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> #SubStore #更新记录 #changlog #updates #安全 #泄露 #防扫 #贴士</div><p class="telegram-source"><a href="https://t.me/zhetengsha/3481">查看 Telegram 原文</a></p>`,3)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};